+impl AsyncRead for WasmTcpStream {
+    fn poll_read(
+        self: Pin<&mut Self>,
+        cx: &mut Context<'_>,
+        buf: &mut [u8],
+    ) -> Poll<io::Result<usize>> {
+        let mut s = self.stack.lock().unwrap();
+        let socket = s.sockets.get_mut::<smoltcp_tcp::Socket>(self.handle);
