+impl AsyncWrite for WasmTcpStream {
+    fn poll_write(
+        self: Pin<&mut Self>,
+        cx: &mut Context<'_>,
+        buf: &[u8],
+    ) -> Poll<io::Result<usize>> {
+        let mut s = self.stack.lock().unwrap();
+        let socket = s.sockets.get_mut::<smoltcp_tcp::Socket>(self.handle);
+
+        if socket.can_send() {
+            let n = socket
+                .send_slice(buf)
